H,W=23,27
marks={
0:[14,24],1:[0,6,9,15,19,23],2:[19,23],3:[1,3,4,13,15,17],
5:[3,6,10,23,24],6:[3,12,22],7:[1,24],8:[23],9:[4,7,22],
10:[3,10,16],11:[1,11,21],12:[0,7,9,14,18],13:[13,14,23,25],14:[24],
15:[2,9,18],16:[3],17:[2,7,11,22,23,26],18:[2,16,19],
19:[8,10,20],20:[2,17,25],21:[6,24],22:[9,22]}
g=[[6]*W for _ in range(H)]
for r,cs in marks.items():
 for c in cs:g[r][c]=7
edits=set()
for r,cs in marks.items():
 for a,b in zip(cs,cs[1:]): edits.update((r,c) for c in range(a+1,b))
for c in range(W):
 rs=[r for r in range(H) if g[r][c]==7]
 for a,b in zip(rs,rs[1:]): edits.update((r,c) for r in range(a+1,b))
assert all(g[r][c]==6 for r,c in edits)
out=[[3 if (r,c) in edits else g[r][c] for c in range(W)] for r in range(H)]
print('marks',sum(map(len,marks.values())),'filled',len(edits),'dimensions',len(out),len(out[0]))
for row in out:print('['+','.join(map(str,row))+'],')
